  private constructor() {
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });
  }

  public static getInstance(): GeminiService {
    if (!GeminiService.instance) {
      GeminiService.instance = new GeminiService();
    }
    return GeminiService.instance;
  }

  public async askExpert(prompt: string): Promise<string> {
    try {
      const response = await this.ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: {
          systemInstruction: `You are an expert biosecurity consultant for pig and poultry farms. 
          Provide practical, scientifically accurate, and easy-to-implement advice. 
          Keep your answers concise and professional. 
          Use bullet points for lists.`,
          temperature: 0.7,
        },
      });
      return response.text || "I'm sorry, I couldn't process that request.";
    } catch (error) {
      console.error("Gemini API Error:", error);
      return "An error occurred while contacting the AI advisor.";
    }
  }

  public async generateReport(data: LivestockData): Promise<any> {
    try {
      const response = await this.ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Analyze this farm data and generate a structured biosecurity report:
        Pigs: ${data.pigs.count} animals, last vaccinated on ${data.pigs.lastVaccination || 'unknown'}. Note: ${data.pigs.healthNote || 'None'}.
        Hens: ${data.hens.count} animals, last vaccinated on ${data.hens.lastVaccination || 'unknown'}. Note: ${data.hens.healthNote || 'None'}.
        Today is ${new Date().toLocaleDateString()}.`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              summary: { type: Type.STRING },
              healthStatus: { type: Type.STRING, description: "One of: Excellent, Good, Fair, Critical" },
              alerts: { type: Type.ARRAY, items: { type: Type.STRING } },
              recommendations: { type: Type.ARRAY, items: { type: Type.STRING } },
              overallScore: { type: Type.NUMBER, description: "0 to 100" }
            },
            required: ["summary", "healthStatus", "alerts", "recommendations", "overallScore"]
          }
        }
      });
      return JSON.parse(response.text || "{}");
    } catch (error) {
      console.error("Gemini Report Error:", error);
      throw error;
    }
  }
}

